class Component extends DCLogic {
  state = { seen: {} }
  componentDidMount() {
    this._io = new IntersectionObserver(
      (es) => {
        const add = {}
        es.forEach((e) => {
          if (e.isIntersecting) {
            add[e.target.dataset.rv] = true
            this._io.unobserve(e.target)
          }
        })
        if (Object.keys(add).length) this.setState((s) => ({ seen: { ...s.seen, ...add } }))
      },
      { threshold: 0.1 },
    )
    this._t = setTimeout(() => document.querySelectorAll('[data-rv]').forEach((n) => this._io.observe(n)), 100)
  }
  componentWillUnmount() {
    this._io?.disconnect()
    clearTimeout(this._t)
  }
  renderVals() {
    const S = this.state
    return {
      jump: F.map(([id, kind, label]) => ({ kind, label, href: '#' + id })),
      features: F.map(([id, kind, label, title, sub, src, fh, points]) => {
        const on = !!S.seen[id]
        return {
          id,
          kind,
          label,
          title,
          sub,
          src,
          fh,
          points,
          op: on ? 1 : 0,
          tf: on ? 'translateY(0)' : 'translateY(28px)',
          shotTf: on ? 'translateY(0) scale(1)' : 'translateY(40px) scale(.97)',
        }
      }),
    }
  }
}

